<script>
  import { onMount } from 'svelte';
  import { ApiError, completeAction, confirmSipOccurrence, createLoan, createMissingDateContext, createMutualFund, deleteExpense, getActions, getExpenseOptions, getExpensesForDate, getLoans, getMutualFund, getMutualFunds, logout, searchMutualFunds, updateExpense, updateLoan } from './lib/api.js';
  import SectionState from './SectionState.svelte';
  import Normalization from './Normalization.svelte';
  import AppHeader from './components/AppHeader.svelte';
  import BottomNav from './components/BottomNav.svelte';
  import ProfileSettings from './features/profile/ProfileSettings.svelte';
  export let calendarSection; export let recentSection; export let storiesSection; export let selectedMonth; export let connectionStatus; export let cacheUpdatedAt; export let demoMode; export let onDemoModeChange; export let onMonthChange; export let refreshCalendar; export let refreshRecent; export let refreshStories; export let onRetryConnection; export let onLogout;

  let view='home', showMoney=false, showNormalization=false, selectedDay=null, activityTab='recent', dayItems=[], dayStatus='idle', showAll=false, expandedId=null;
  let openedStory=null, handoff=null, addingContext=false, actionError='', loggingOut=false, signOutError='', demoSwitching=false, demoError='', storySlide=0, storyTouchStart=null, showStoryEvidence=false, storyFilter='All';
  let editing=null, editAmount='', editDate='', editCategory='', editSubcategory='', editMerchantId='', editAccountId='', saving=false, deleting=null;
  let editOptions={categories:[],merchants:[],accounts:[]}, optionsStatus='idle', optionsError='';
  let storyControls={spending:true,investments:true,planning:true};
  let showLoanForm=false, loanError='', loanStatus='idle', loanEditingId=null, loanSaving=false;
  let loanForm={loanName:'',loanType:'HOME',lenderName:'',originalPrincipal:'',monthlyEmiAmount:'',totalTenureMonths:'',firstEmiDueDate:'',notes:''};
  let loans=[];
  let showMutualFundForm=false, schemeQuery='', showSchemeMenu=false, selectedScheme=null, fundError='', fundSaved=false, fundSaving=false, schemeSearchStatus='idle', schemeResults=[], schemeSearchRequest=0;
  let mutualFunds=[], mutualFundStatus='idle', mutualFundError='';
  let actions=[], actionsStatus='idle', actionsError='', completingActionId=null;
  let confirmingSip=null, sipConfirmError='', sipConfirmSaving=false, sipConfirmForm={amount:'',transactionDate:new Date().toISOString().slice(0,10),nav:''};
  let fundDetail=null, fundDetailStatus='idle', fundDetailError='';
  const MONEY_MODULES_CACHE_KEY='money-stories.money-modules-cache.v1';
  let fundForm={sipAmount:'25000',sipDate:'5',startMonth:'2026-10',paymentMethod:'AUTOPAY',hasHolding:'YES',currentUnits:'128.456',totalInvested:'10000'};
  $: data=calendarSection.data||{}; $: currency=data.currency||'INR'; $: calendar=buildCalendar(selectedMonth,data.days||[]);
  $: recentData=recentSection.data||{}; $: recentItems=(recentData.items||recentData.expenses||[]).slice(0,5);
  $: storyData=storiesSection.data||{}; $: stories=storyData.stories||storyData.moneyStories||storyData.storyCards||[];
  $: filteredStories=storyFilter==='All'?stories:stories.filter(story=>storySource(story).toLowerCase()===storyFilter.toLowerCase());
  $: selected=selectedDay==null?null:calendar.days.find(day=>day.day===selectedDay); $: activeItems=activityTab==='recent'?recentItems:dayItems; $: visibleItems=showAll?activeItems:activeItems.slice(0,5);
  $: editSubcategories=editOptions.categories.find(option=>option.name===editCategory)?.subcategories||[];
  $: totalMonthlyEmi=loans.reduce((total,loan)=>total+Number(loan.monthlyEmiAmount||0),0);
  $: mutualPortfolio={invested:mutualFunds.reduce((total,fund)=>total+Number(fund.invested||0),0),current:mutualFunds.some(fund=>fund.currentValue!==null)?mutualFunds.reduce((total,fund)=>total+Number(fund.currentValue||0),0):null,pnl:mutualFunds.some(fund=>fund.profitOrLoss!==null)?mutualFunds.reduce((total,fund)=>total+Number(fund.profitOrLoss||0),0):null};
  $: visibleActions=actions.map(action=>({action,presentation:actionPresentation(action)})).filter(item=>item.presentation);
  const money=value=>new Intl.NumberFormat('en-IN',{style:'currency',currency,maximumFractionDigits:0}).format(Number(value||0));
  const moneyDecimal=value=>new Intl.NumberFormat('en-IN',{style:'currency',currency,minimumFractionDigits:2,maximumFractionDigits:2}).format(Number(value||0));
  const compactMoney=value=>new Intl.NumberFormat('en-IN',{style:'currency',currency,notation:'compact',maximumFractionDigits:2}).format(Number(value||0));
  const fundSubtitle=name=>/growth/i.test(name)?'Growth · Direct plan':'Verified scheme'; const fundAccent=id=>['coral','gold','violet','blue'][Number(id||0)%4];
  const merchant=item=>item.merchant||item.merchantName||item.description||item.originalMessage||'Expense'; const category=item=>item.category?.name||item.category||'Uncategorised'; const transactionDate=item=>item.transactionDate||item.transactionTime||item.date;
  const dateLabel=value=>value?new Intl.DateTimeFormat(undefined,{day:'numeric',month:'short'}).format(new Date(value)):'';
  const monthLabel=value=>{const[y,m]=value.split('-').map(Number);return new Intl.DateTimeFormat(undefined,{month:'long',year:'numeric'}).format(new Date(y,m-1));};
  const greeting=()=>new Date().getHours()<12?'Good morning':new Date().getHours()<17?'Good afternoon':'Good evening'; const isoDate=day=>`${selectedMonth}-${String(day).padStart(2,'0')}`;
  const hasDeck=story=>Array.isArray(story.cards)&&story.cards.length>0; const storyName=story=>String(story.storyType||story.type||'Money story').replaceAll('_',' '); const storyTone=story=>story.cardFace?.theme||'calm'; const storyCardFace=story=>story.cardFace||{heading:'Money story',displayValue:'View',theme:'calm'}; const storySource=story=>story.source||story.domain||'Spending';
  $: connectionLabel=connectionStatus==='online'?'Online':connectionStatus==='offline'?'Offline':'Checking';
  $: evidenceItems=evidenceFor(openedStory);
  function localInputDate(value){if(!value)return '';const text=String(value);if(/^\d{4}-\d{2}-\d{2}$/.test(text))return text;const date=new Date(text);return Number.isNaN(date.getTime())?text.slice(0,10):`${date.getFullYear()}-${String(date.getMonth()+1).padStart(2,'0')}-${String(date.getDate()).padStart(2,'0')}`;}
  function evidenceFor(story){const evidence=story?.evidence;const raw=Array.isArray(evidence)?evidence:evidence?.transactions||evidence?.items||story?.transactions||[];return raw.map(item=>({merchant:item.merchantLabel||item.merchant||item.merchantName||item.description||'Expense',category:item.categoryLabel||item.category?.name||item.category||'Uncategorised',date:item.dateLabel||dateLabel(item.transactionDate||item.transactionTime||item.date),amount:item.amount?.displayValue||item.displayAmount||money(item.amount)}));}
  function loanSchedule(loan){const first=new Date(`${loan.firstEmiDueDate}T12:00:00`);if(Number.isNaN(first.getTime()))return null;const today=new Date(),tenure=Number(loan.totalTenureMonths)||0,elapsedMonths=(today.getFullYear()-first.getFullYear())*12+today.getMonth()-first.getMonth(),due=Math.max(0,Math.min(tenure,elapsedMonths+(today.getDate()>=first.getDate()?1:0))),remaining=Math.max(0,tenure-due),finalDue=new Date(first.getFullYear(),first.getMonth()+Math.max(0,tenure-1),first.getDate());return{due,remaining,tenure,percent:tenure?Math.round(due/tenure*100):0,endLabel:new Intl.DateTimeFormat(undefined,{month:'short',year:'numeric'}).format(finalDue)};}
  function actionPresentation(action){if(action.actionType==='LOAN_CLOSURE_CONFIRMATION'){const scheduled=action.scheduledCompletionDate?new Intl.DateTimeFormat(undefined,{day:'numeric',month:'short',year:'numeric'}).format(new Date(`${action.scheduledCompletionDate}T12:00:00`)):'';const description=(action.description||`EMI was scheduled to finish on ${scheduled}.`).replace(action.scheduledCompletionDate||'',scheduled).replace(/\s*Mark it closed if the final EMI was paid\.?\s*$/i,'');return{title:'Loan closure confirmation',description,cta:'Mark loan closed'};}return null;}
  const moneyModulesCacheKey=()=>`${MONEY_MODULES_CACHE_KEY}.${demoMode?'demo':'real'}`;
  function readMoneyModulesCache(){try{const cached=JSON.parse(localStorage.getItem(moneyModulesCacheKey())||'null');if(!cached)return false;if(Array.isArray(cached.loans)){loans=cached.loans;loanStatus='ready';}if(Array.isArray(cached.mutualFunds)){mutualFunds=cached.mutualFunds;mutualFundStatus='ready';}return true;}catch{return false;}}
  function saveMoneyModulesCache(){try{localStorage.setItem(moneyModulesCacheKey(),JSON.stringify({updatedAt:new Date().toISOString(),loans,mutualFunds}));}catch{/* The live modules still work if storage is unavailable. */}}
  async function loadLoans(){loanStatus=loans.length?'refreshing':'loading';try{const result=await getLoans();loans=result.loans||[];loanStatus='ready';saveMoneyModulesCache();}catch(cause){if(loans.length){loanStatus='ready';return;}loanStatus='error';loanError=cause?.message||'Could not load loans.';}}
  async function loadMutualFunds(){mutualFundStatus=mutualFunds.length?'refreshing':'loading';mutualFundError='';try{const result=await getMutualFunds();mutualFunds=result.mutualFunds||[];mutualFundStatus='ready';saveMoneyModulesCache();}catch(cause){if(mutualFunds.length){mutualFundStatus='ready';return;}mutualFundStatus='error';mutualFundError=cause?.message||'Could not load mutual funds.';}}
  async function loadActions(){actionsStatus=actions.length?'refreshing':'loading';actionsError='';try{const result=await getActions();actions=result.actions||[];actionsStatus='ready';}catch(cause){actionsStatus='error';actionsError=cause?.message||'Could not load actions.';}}
  async function completeOpenAction(action){if(completingActionId!==null)return;completingActionId=action.id;actionsError='';try{await completeAction(action.id);actions=actions.filter(item=>item.id!==action.id);await Promise.all([loadLoans(),loadActions()]);}catch(cause){actionsError=cause?.message||'Could not complete this action.';}finally{completingActionId=null;}}
  async function openMoney(){showMoney=true;readMoneyModulesCache();await Promise.all([loadLoans(),loadMutualFunds()]);}
  function openLoanForm(loan=null){loanError='';loanEditingId=loan?.id??null;loanForm=loan?{loanName:loan.loanName||'',loanType:loan.loanType||'HOME',lenderName:loan.lenderName||'',originalPrincipal:String(loan.originalPrincipal??''),monthlyEmiAmount:String(loan.monthlyEmiAmount??''),totalTenureMonths:String(loan.totalTenureMonths??''),firstEmiDueDate:localInputDate(loan.firstEmiDueDate),notes:loan.notes||''}:{loanName:'',loanType:'HOME',lenderName:'',originalPrincipal:'',monthlyEmiAmount:'',totalTenureMonths:'',firstEmiDueDate:'',notes:''};showLoanForm=true;}
  async function saveLoan(){const originalPrincipal=Number(loanForm.originalPrincipal),monthlyEmiAmount=Number(loanForm.monthlyEmiAmount),totalTenureMonths=Number(loanForm.totalTenureMonths);if(!loanForm.loanName.trim()||!loanForm.lenderName.trim()||!loanForm.firstEmiDueDate||originalPrincipal<=0||monthlyEmiAmount<=0||!Number.isInteger(totalTenureMonths)||totalTenureMonths<=0){loanError='Complete every required loan detail with valid positive amounts.';return;}const payload={loanName:loanForm.loanName.trim(),loanType:loanForm.loanType,lenderName:loanForm.lenderName.trim(),originalPrincipal,monthlyEmiAmount,totalTenureMonths,firstEmiDueDate:loanForm.firstEmiDueDate,notes:loanForm.notes};loanSaving=true;loanError='';try{const saved=loanEditingId==null?await createLoan(payload):await updateLoan(loanEditingId,payload);loans=loanEditingId==null?[...loans,saved]:loans.map(loan=>loan.id===saved.id?saved:loan);showLoanForm=false;loanStatus='ready';}catch(cause){loanError=cause?.message||'Could not save this loan.';}finally{loanSaving=false;}}
  function openMutualFundForm(){fundError='';fundSaved=false;schemeQuery='';selectedScheme=null;showSchemeMenu=false;fundForm={sipAmount:'25000',sipDate:'5',startMonth:'2026-10',paymentMethod:'AUTOPAY',hasHolding:'YES',currentUnits:'128.456',totalInvested:'10000'};showMutualFundForm=true;}
  async function searchSchemes(value){schemeQuery=value;selectedScheme=null;showSchemeMenu=true;fundError='';if(value.trim().length<2){schemeResults=[];schemeSearchStatus='idle';return;}const requestId=++schemeSearchRequest;schemeSearchStatus='loading';try{const result=await searchMutualFunds(value.trim());if(requestId!==schemeSearchRequest)return;schemeResults=Array.isArray(result)?result:result.schemes||[];schemeSearchStatus='ready';}catch(cause){if(requestId!==schemeSearchRequest)return;schemeResults=[];schemeSearchStatus='error';fundError=cause?.message||'Could not search the scheme master.';}}
  function selectScheme(scheme){selectedScheme=scheme;schemeQuery=scheme.schemeName;showSchemeMenu=false;fundError='';}
  async function saveMutualFund(){const sipAmount=Number(fundForm.sipAmount),units=Number(fundForm.currentUnits),invested=Number(fundForm.totalInvested);if(!selectedScheme){fundError='Choose a scheme from the verified scheme master.';return;}if(sipAmount<=0||!fundForm.sipDate||!fundForm.startMonth){fundError='Add a valid monthly amount, SIP date, and start month.';return;}if(fundForm.hasHolding==='YES'&&(!(units>0)||!(invested>0))){fundError='Enter current units and invested amount greater than zero.';return;}const payload={schemeCode:selectedScheme.schemeCode,schemeName:selectedScheme.schemeName,monthlySipAmount:sipAmount,sipDay:Number(fundForm.sipDate),startMonth:fundForm.startMonth,...(selectedScheme.isin?{isin:selectedScheme.isin}:{}),...(fundForm.hasHolding==='YES'?{existingHolding:{currentUnits:units,totalInvestedAmount:invested}}:{})};fundSaving=true;fundError='';try{await createMutualFund(payload);fundSaved=true;await loadMutualFunds();}catch(cause){fundError=cause?.message||'Could not create this mutual fund.';}finally{fundSaving=false;}}
  function openSipConfirmation(fund,occurrence){confirmingSip={fund,occurrence};sipConfirmError='';sipConfirmForm={amount:String(occurrence.amount||fund.monthlySipAmount||''),transactionDate:new Date().toISOString().slice(0,10),nav:''};}
  async function saveSipConfirmation(){const amount=Number(sipConfirmForm.amount),nav=Number(sipConfirmForm.nav);if(!(amount>0)||!sipConfirmForm.transactionDate||!(nav>0)){sipConfirmError='Enter a valid amount, transaction date, and NAV.';return;}sipConfirmSaving=true;sipConfirmError='';try{await confirmSipOccurrence(confirmingSip.fund.id,confirmingSip.occurrence.scheduledMonth,{amount,transactionDate:sipConfirmForm.transactionDate,nav,calculationSource:'NAV_ESTIMATED'});confirmingSip=null;await loadMutualFunds();}catch(cause){sipConfirmError=cause?.message||'Could not confirm this SIP.';}finally{sipConfirmSaving=false;}}
  async function openFundDetail(id){fundDetail={id};fundDetailStatus='loading';fundDetailError='';try{fundDetail=await getMutualFund(id);fundDetailStatus='ready';}catch(cause){fundDetailStatus='error';fundDetailError=cause?.message||'Could not load this fund.';}}
  function navigate(next){view=next;if(next!=='transactions'){selectedDay=null;activityTab='recent';}window.scrollTo({top:0,behavior:'smooth'});}
  function currentLocalMonth(){const now=new Date();return `${now.getFullYear()}-${String(now.getMonth()+1).padStart(2,'0')}`;}
  function changeMonth(offset){const[y,m]=selectedMonth.split('-').map(Number),next=new Date(Date.UTC(y,m-1+offset,1)).toISOString().slice(0,7);if(next<=currentLocalMonth()){selectedDay=null;dayItems=[];activityTab='recent';onMonthChange(next);}}
  function buildCalendar(monthValue,apiDays){const[y,m]=monthValue.split('-').map(Number),count=new Date(y,m,0).getDate(),leading=(new Date(y,m-1,1).getDay()+6)%7,values=new Map(apiDays.map(x=>[Number(String(x.date).slice(-2)),x])),today=new Date(),current=today.getFullYear()===y&&today.getMonth()+1===m;return{leading,days:Array.from({length:count},(_,i)=>{const day=i+1,v=values.get(day)||{};return{day,totalSpend:Number(v.totalSpend||0),transactionCount:Number(v.transactionCount||0),intensity:Math.max(0,Math.min(4,Number(v.intensity||0))),future:current&&day>today.getDate()};})};}
  async function selectDate(day){if(!day||day.future)return;selectedDay=day.day;activityTab='day';showAll=false;expandedId=null;await loadDay();}
  async function loadDay(){if(selectedDay==null)return;dayStatus='loading';try{const page=await getExpensesForDate(selectedMonth,isoDate(selectedDay),50);dayItems=page.items||page.expenses||[];dayStatus='ready';}catch{dayStatus='error';}}
  function openStory(story){openedStory=story;storySlide=0;showStoryEvidence=false;}
  function endStorySwipe(event,length){if(storyTouchStart===null)return;const distance=event.changedTouches[0].clientX-storyTouchStart;if(Math.abs(distance)>45)storySlide=Math.max(0,Math.min(length-1,storySlide+(distance<0?1:-1)));storyTouchStart=null;}
  async function startEdit(item){editing=item;editAmount=String(item.amount??'');editDate=localInputDate(transactionDate(item));editCategory=category(item)==='Uncategorised'?'':category(item);editSubcategory=item.subcategory?.name||item.subcategory||'';editMerchantId=String(item.merchantId??item.merchant?.id??'');editAccountId=String(item.accountId??item.account?.id??item.sourceAccountId??'');actionError='';optionsError='';if(optionsStatus==='ready'){selectCurrentReferences(item);return;}optionsStatus='loading';try{const result=await getExpenseOptions();editOptions={categories:result.categories||[],merchants:result.merchants||[],accounts:result.accounts||[]};optionsStatus='ready';selectCurrentReferences(item);}catch(cause){optionsStatus='error';optionsError=cause?.message||'Could not load expense options.';}}
  function selectCurrentReferences(item){if(!editMerchantId){const match=editOptions.merchants.find(option=>option.name?.toLowerCase()===merchant(item).toLowerCase());if(match)editMerchantId=String(match.id);}if(!editAccountId){const current=String(item.account?.name??item.sourceAccount?.name??item.accountName??'').toLowerCase(),match=editOptions.accounts.find(option=>option.name?.toLowerCase()===current);if(match)editAccountId=String(match.id);}}
  function changeEditCategory(event){editCategory=event.currentTarget.value;if(!editSubcategories.includes(editSubcategory))editSubcategory='';}
  async function saveEdit(){const amount=Number(editAmount),merchantId=Number(editMerchantId),accountId=Number(editAccountId);if(!editing||saving||optionsStatus!=='ready'||!Number.isFinite(amount)||amount<=0||!editDate||!editCategory||!editSubcategory||!Number.isFinite(merchantId)||!Number.isFinite(accountId))return;saving=true;actionError='';try{await updateExpense(editing.id,{amount,transactionDate:editDate,category:editCategory,subcategory:editSubcategory,merchantId,accountId});editing=null;await Promise.all([loadDay(),refreshRecent(),refreshCalendar(),refreshStories()]);}catch(cause){actionError=cause?.message||'Could not update the transaction.';}finally{saving=false;}}
  async function confirmDelete(){if(!deleting)return;try{await deleteExpense(deleting.id);deleting=null;await Promise.all([loadDay(),refreshRecent(),refreshCalendar(),refreshStories()]);}catch(cause){actionError=cause?.message||'Could not delete the transaction.';deleting=null;}}
  async function addMissingDate(){if(!selected||addingContext)return;addingContext=true;try{const result=await createMissingDateContext(isoDate(selected.day),data.timezone||Intl.DateTimeFormat().resolvedOptions().timeZone);handoff={...result,date:isoDate(selected.day)};}catch(cause){actionError=cause instanceof ApiError?cause.message:'Could not prepare WhatsApp recording.';}finally{addingContext=false;}}
  async function signOut(){loggingOut=true;try{await logout();try{localStorage.removeItem(`${MONEY_MODULES_CACHE_KEY}.real`);localStorage.removeItem(`${MONEY_MODULES_CACHE_KEY}.demo`);}catch{}onLogout();}catch{loggingOut=false;signOutError='Could not sign out.';}}
  async function switchDemoMode(){if(demoSwitching)return;demoSwitching=true;demoError='';try{await onDemoModeChange(!demoMode);loans=[];mutualFunds=[];actions=[];loanStatus='idle';mutualFundStatus='idle';actionsStatus='idle';fundDetail=null;dayItems=[];selectedDay=null;editOptions={categories:[],merchants:[],accounts:[]};optionsStatus='idle';showMoney=false;await loadActions();}catch(cause){demoError=cause?.message||'Could not switch profiles.';}finally{demoSwitching=false;}}
  onMount(loadActions);
</script>

<AppHeader {connectionStatus} {connectionLabel} onRetry={onRetryConnection} onHome={() => navigate('home')} onProfile={() => navigate('you')} />
<main class="app-shell">
{#if connectionStatus==='offline'}<section class="offline-notice"><span>◌</span><div><strong>{cacheUpdatedAt?'Showing your last saved view':'You’re offline'}</strong><p>{cacheUpdatedAt?'We’ll refresh automatically when the service is back.':'Your layout is ready. Connect once to load your expenses and stories.'}</p></div><button on:click={onRetryConnection}>Retry</button></section>{/if}
{#if view==='home'}
  <section class="app-heading"><div><p class="micro-label">{monthLabel(selectedMonth).toUpperCase()}</p><h1>{greeting()}</h1><p>Here’s how your month is unfolding.</p></div></section>
  <SectionState section={calendarSection} title="Spending overview" retry={refreshCalendar}><button class="spending-hero" on:click={()=>navigate('transactions')}><span>MONTHLY SPENDING</span><strong>{money(data.totalSpend)} <small>spent</small></strong><b>{data.transactionCount||0} transactions · View transactions →</b></button></SectionState>
  <section class="home-section"><div class="section-title"><div><p class="micro-label">YOUR STORIES</p><h2>Small signals, clearly told</h2></div><button class="text-link" on:click={()=>navigate('stories')}>See all</button></div><SectionState section={storiesSection} title="Your stories" retry={refreshStories}><div class="home-story-list">{#each stories.slice(0,2) as story}<button class={`home-story ${storyTone(story)}`} on:click={()=>openStory(story)}><span class="story-source">{storySource(story)}</span><strong>{storyCardFace(story).heading}</strong><b>{storyCardFace(story).displayValue}</b><i>›</i></button>{:else}<div class="story-rail-empty">Your stories will appear here as you add expenses.</div>{/each}</div></SectionState></section>
  {#if actionsStatus==='loading'}<section class="home-section action-queue-loading">Loading actions…</section>{:else if actionsStatus==='error'}<section class="home-section"><div class="section-error"><p>{actionsError}</p><button on:click={loadActions}>Try again</button></div></section>{:else if visibleActions.length}<section class="home-section action-queue"><div class="section-title"><div><p class="micro-label">NEEDS YOUR ATTENTION</p><h2>Needs your attention</h2></div></div>{#if actionsError}<div class="section-error"><p>{actionsError}</p><button on:click={loadActions}>Try again</button></div>{/if}<div class="action-card-list">{#each visibleActions as item}<article class="action-card"><span class="action-icon">!</span><div><strong>{item.presentation.title}</strong><p>{item.presentation.description}</p><button class="primary action-complete" disabled={completingActionId!==null} on:click={()=>completeOpenAction(item.action)}>{completingActionId===item.action.id?'Marking loan closed…':item.presentation.cta}</button></div></article>{/each}</div></section>{/if}
  <section class="home-section"><div class="section-title"><div><p class="micro-label">RECENT ACTIVITY</p><h2>Your latest expenses</h2></div><button class="text-link" on:click={()=>navigate('transactions')}>See all</button></div><div class="compact-list">{#each recentItems.slice(0,3) as item}<button class="row-main" on:click={()=>{navigate('transactions');startEdit(item);}}><div><strong>{merchant(item)}</strong><span>{category(item)} · {dateLabel(transactionDate(item))}</span></div><b>− {money(item.amount)}</b></button>{:else}<p class="empty-copy">No expenses recorded yet.</p>{/each}</div></section>
  <button class="your-money-card" on:click={openMoney}><span>◒</span><div><strong>Your money</strong><small>Add goals, investments or a safety fund when you’re ready.</small></div><b>Explore ›</b></button>
{:else if view==='transactions'}
  <section class="workspace-heading"><div><p class="micro-label">EXPENSE WORKSPACE</p><h1>Transactions</h1><p>AI-captured expenses, ready for your review.</p></div><label class="month-switcher"><button type="button" on:click={()=>changeMonth(-1)}>←</button><input type="month" value={selectedMonth} max={currentLocalMonth()} on:change={e=>onMonthChange(e.currentTarget.value)}/><button type="button" on:click={()=>changeMonth(1)}>→</button></label></section>
  <SectionState section={calendarSection} title="Spending calendar" retry={refreshCalendar}><section class="month-card"><div class="month-summary"><div><span>Total recorded</span><strong>{money(data.totalSpend)}</strong></div><div><span>Transactions</span><strong>{data.transactionCount||0}</strong></div><div><span>Highest day</span><strong>{money(data.highestSpend)}</strong></div></div><div class="weekdays">{#each ['Mon','Tue','Wed','Thu','Fri','Sat','Sun'] as d}<span>{d}</span>{/each}</div><div class="calendar">{#each Array(calendar.leading) as _}<span></span>{/each}{#each calendar.days as d}<button class:future={d.future} class:selected={selectedDay===d.day} class={`level-${d.intensity}`} disabled={d.future} on:click={()=>selectDate(d)}>{d.day}</button>{/each}</div><div class="legend"><span>Lower spend</span><div>{#each [0,1,2,3,4] as l}<i class={`level-${l}`}></i>{/each}</div><span>Higher spend</span></div></section></SectionState>
  <section class="activity-panel adaptive-activity"><div class="activity-tabs"><button class:active={activityTab==='recent'} on:click={()=>activityTab='recent'}>Recent</button><button class:active={activityTab==='day'} on:click={()=>activityTab='day'}>{selected?`${selected.day} selected`:'Select a date'}</button></div>{#if activityTab==='day'&&dayStatus==='loading'}<div class="activity-loading">Loading transactions…</div>{:else if activityTab==='day'&&dayStatus==='error'}<div class="section-error"><p>Could not load this date.</p><button on:click={loadDay}>Try again</button></div>{:else}<div class="activity-summary"><p class="micro-label">{activityTab==='recent'?'RECENT EXPENSES':selected?`${selected.day} ${monthLabel(selectedMonth)}`:'SELECT A DATE'}</p><h2>{activityTab==='recent'?`${recentItems.length} recent transactions`:selected?`${selected.transactionCount} transactions · ${money(selected.totalSpend)}`:'Choose a date in the calendar'}</h2></div><div class="compact-list">{#each visibleItems as item}<article class:expanded={expandedId===item.id} class="compact-row"><button class="row-main" on:click={()=>expandedId=expandedId===item.id?null:item.id}><div><strong>{merchant(item)}</strong><span>{category(item)} · {dateLabel(transactionDate(item))}</span></div><div class="row-value"><b>− {money(item.amount)}</b><span class:open={expandedId===item.id} class="row-chevron">⌄</span></div></button>{#if expandedId===item.id}<div class="row-actions"><button on:click={()=>startEdit(item)}>Edit transaction</button><button class="danger" on:click={()=>deleting=item}>Delete</button></div>{/if}</article>{:else}<p class="empty-copy">No transactions for this view.</p>{/each}</div>{#if activeItems.length>5}<button class="view-all" on:click={()=>showAll=!showAll}>{showAll?'Show fewer ↑':`View all ${activeItems.length} transactions ↓`}</button>{/if}{/if}</section>
  <button class="wide-button" disabled={!selected||addingContext} on:click={addMissingDate}>{addingContext?'Preparing WhatsApp…':selected?'+ Add missing expense':'Select a date to add an expense'}</button><button class="cleanup-card" on:click={()=>showNormalization=true}><span>✦</span><div><strong>Expense cleanup</strong><small>Fix merchant and account names captured by AI.</small></div><b>Open ›</b></button>
{:else if view==='stories'}
  <section class="workspace-heading"><div><p class="micro-label">YOUR MONEY, EXPLAINED</p><h1>Stories</h1><p>Insights across the information you choose to share.</p></div></section><div class="story-filters">{#each ['All','Spending','Investing','Planning'] as filter}<button class:active={storyFilter===filter} on:click={()=>storyFilter=filter}>{filter}</button>{/each}</div><SectionState section={storiesSection} title="Stories" retry={refreshStories}><div class="stories-feed">{#each filteredStories as story}<button class={`feed-story ${storyTone(story)}`} on:click={()=>openStory(story)}><span class="story-source">{storySource(story)}</span><strong>{storyCardFace(story).heading}</strong><b>{storyCardFace(story).displayValue}</b><i>›</i></button>{:else}<div class="empty-state"><span>✦</span><h2>No {storyFilter.toLowerCase()} stories yet</h2><p>As you choose to add more information, relevant stories will appear here.</p></div>{/each}</div></SectionState>
{:else}
  <ProfileSettings {demoMode} {demoSwitching} {demoError} {loggingOut} {signOutError} {storyControls} onNavigate={navigate} onOpenMoney={openMoney} onDemoModeChange={switchDemoMode} onSignOut={signOut} />
{/if}
</main>
<BottomNav {view} onNavigate={navigate} />

<!-- svelte-ignore a11y_click_events_have_key_events -->
{#if showMoney}
  <div class="modal-backdrop" on:click={()=>showMoney=false} on:keydown={(event)=>event.key==='Escape'&&(showMoney=false)} role="presentation">
    <section class="modal money-modal" on:click|stopPropagation role="dialog" aria-modal="true" tabindex="-1">
      <button class="close" on:click={()=>showMoney=false}>×</button>
      <p class="micro-label">OPTIONAL, PRIVATE, YOURS</p><h2>Build your complete money picture</h2>
      <p class="module-reassurance">You choose what to add. Nothing is required, and you can remove a module anytime.</p>
      {#each [['◒','Emergency fund','Track your safety cushion'],['◎','Goals','Plan for what matters'],['▤','Budgets','Set gentle spending limits']] as module}
        <button class="module-row" on:click={()=>showMoney=false}><span>{module[0]}</span><div><strong>{module[1]}</strong><small>{module[2]}</small></div><b>Coming soon</b></button>
      {/each}
      <section class="mutual-funds-module"><div class="loans-heading"><div><strong>Mutual funds</strong><small>Portfolio value from the latest available NAV</small></div><span class="verified-pill">Scheme API</span></div>{#if mutualFundStatus==='loading'}<p>Loading your funds…</p>{:else if mutualFundStatus==='error'}<div class="loan-state error"><span>{mutualFundError}</span><button on:click={loadMutualFunds}>Try again</button></div>{:else if mutualFunds.length}<section class="portfolio-total"><span>Total portfolio value</span>{#if mutualPortfolio.current!==null}<strong>{money(mutualPortfolio.current)}</strong><small class:positive={mutualPortfolio.pnl>=0} class:negative={mutualPortfolio.pnl<0}>{mutualPortfolio.pnl>=0?'+':''}{money(mutualPortfolio.pnl)} overall P&amp;L</small>{:else}<strong>{money(mutualPortfolio.invested)}</strong><small>Current valuation is temporarily unavailable</small>{/if}</section><div class="fund-card-list">{#each mutualFunds as fund}<button class={`fund-card ${fundAccent(fund.id)}`} on:click={()=>openFundDetail(fund.id)} aria-label={`Open ${fund.schemeName} details`}><span class="fund-card-orb"></span><div class="fund-card-title"><strong>{fund.schemeName}</strong><small>{fundSubtitle(fund.schemeName)}</small></div>{#if fund.currentValue!==null}<div class="fund-card-values"><div class:positive={Number(fund.profitOrLoss)>=0} class:negative={Number(fund.profitOrLoss)<0}><span>P&amp;L</span><b>{Number(fund.profitOrLoss)>=0?'+':''}{compactMoney(fund.profitOrLoss)}</b><small>{Number(fund.profitOrLossPercent)>=0?'+':''}{Number(fund.profitOrLossPercent).toFixed(2)}%</small></div><div><span>Invested</span><b>{compactMoney(fund.invested)}</b></div><div><span>Current</span><b>{compactMoney(fund.currentValue)}</b></div></div><p class="fund-card-nav">Latest NAV {moneyDecimal(fund.latestNav)}</p>{:else}<p class="fund-valuation-unavailable">Current valuation is temporarily unavailable. Your invested amount is {money(fund.invested)}.</p>{/if}<footer>{fund.activeSip?`1 SIP · ${compactMoney(fund.activeSip.amount)} on the ${fund.activeSip.day}${fund.activeSip.day===1?'st':fund.activeSip.day===2?'nd':fund.activeSip.day===3?'rd':'th'} of every month`:'No active SIP'}<span>View details →</span></footer></button>{/each}</div>{:else}<p>Choose one verified scheme, then add only the details needed for your SIP.</p>{/if}<button class="add-fund-row" on:click={openMutualFundForm}>＋ Add a mutual fund</button></section>
      <section class="loans-module"><div class="loans-heading"><div><strong>Loans</strong><small>Track repayments and monthly commitments</small></div>{#if loans.length}<div class="loan-total"><span>Total monthly EMI</span><b>{money(totalMonthlyEmi)}/mo</b></div>{/if}</div>
        {#if loanStatus==='loading'}<p class="loan-state">Loading your loans…</p>{:else if loanStatus==='error'}<div class="loan-state error"><span>{loanError}</span><button on:click={loadLoans}>Try again</button></div>{:else if loans.length}{#each loans as loan}{@const schedule=loanSchedule(loan)}<article class="loan-row"><span>₹</span><div><strong class="loan-name">{loan.loanName}<button class="loan-edit" on:click={()=>openLoanForm(loan)} aria-label={`Edit ${loan.loanName}`} title="Edit loan">🔧</button></strong><small>{loan.lenderName} · {loan.loanType.replaceAll('_',' ')} · {loan.totalTenureMonths} months</small></div><div><b>{money(loan.monthlyEmiAmount)}/mo</b><small>{money(loan.originalPrincipal)} principal</small></div>{#if schedule}<div class="loan-progress" aria-label={`${schedule.due} of ${schedule.tenure} EMIs due till ${schedule.endLabel}`}><div><span>{schedule.due} of {schedule.tenure} EMIs due till {schedule.endLabel}</span></div><i style={`--loan-progress:${schedule.percent}%`}></i></div>{/if}</article>{/each}{:else}<p class="loan-state">No loans added yet.</p>{/if}
        <button class="add-loan-row" on:click={()=>openLoanForm()}>＋ Add another loan</button>
      </section>
      <p class="module-footnote">These modules use normal forms—not AI cleanup—and only inform stories if you turn that on.</p>
    </section>
  </div>
{/if}
{#if showLoanForm}
  <div class="modal-backdrop loan-form-backdrop" role="presentation"><section class="modal loan-form" role="dialog" aria-modal="true" tabindex="-1"><button class="close" on:click={()=>showLoanForm=false}>×</button><p class="micro-label">LOAN DETAILS</p><h2>{loanEditingId==null?'Add a loan':'Edit loan'}</h2><p class="module-reassurance">Your loan information is stored securely in your account.</p><label>Loan name<input bind:value={loanForm.loanName} placeholder="e.g. HDFC Home Loan" maxlength="255" /></label><label>Loan type<select bind:value={loanForm.loanType}>{#each ['HOME','VEHICLE','PERSONAL','EDUCATION','CREDIT_CARD_EMI','OTHER'] as type}<option value={type}>{type.replaceAll('_',' ')}</option>{/each}</select></label><label>Original loan principal<input type="number" inputmode="decimal" min="1" bind:value={loanForm.originalPrincipal} placeholder="e.g. 4200000" /></label><label>Monthly EMI amount<input type="number" inputmode="decimal" min="1" bind:value={loanForm.monthlyEmiAmount} placeholder="e.g. 38600" /></label><label>Total tenure in months<input type="number" inputmode="numeric" min="1" bind:value={loanForm.totalTenureMonths} placeholder="e.g. 240" /></label><label>First EMI due date<input type="date" bind:value={loanForm.firstEmiDueDate} /></label><label>Bank / lender<input bind:value={loanForm.lenderName} placeholder="e.g. HDFC Bank" maxlength="255" /></label><label>Notes <span class="optional">Optional</span><input bind:value={loanForm.notes} placeholder="e.g. Primary residence" /></label>{#if loanError}<p class="form-error">{loanError}</p>{/if}<div class="modal-actions"><button class="secondary" on:click={()=>showLoanForm=false}>Cancel</button><button class="primary" on:click={saveLoan} disabled={loanSaving}>{loanSaving?'Saving…':loanEditingId==null?'Add loan':'Save changes'}</button></div></section></div>
{/if}
{#if showMutualFundForm}
  <div class="modal-backdrop fund-form-backdrop" role="presentation"><section class="modal fund-form" role="dialog" aria-modal="true" tabindex="-1"><button class="close" on:click={()=>showMutualFundForm=false}>×</button>
    {#if fundSaved}<div class="fund-success"><span>✓</span><p class="micro-label">SIP READY</p><h2>Your SIP is set up</h2><p>{money(fundForm.sipAmount)} will be tracked monthly for {selectedScheme.schemeName}. The first occurrence will be due in {monthLabel(fundForm.startMonth)}.</p><button class="primary" on:click={()=>showMutualFundForm=false}>Done</button></div>
    {:else}<p class="micro-label">MUTUAL FUND · MONTHLY SIP</p><h2>Add a mutual fund</h2><p class="module-reassurance">Search the official scheme master. A returned name is one verified fund, plan and option.</p>
      <div class="fund-section"><span class="fund-section-label">1 · FUND</span><label class="scheme-picker">Search and select scheme<input value={schemeQuery} on:focus={()=>showSchemeMenu=true} on:input={e=>searchSchemes(e.currentTarget.value)} placeholder="Type at least 2 characters" autocomplete="off" />{#if showSchemeMenu}<div class="scheme-menu">{#if schemeSearchStatus==='loading'}<p>Searching schemes…</p>{:else if schemeQuery.trim().length<2}<p>Type at least 2 characters to search.</p>{:else}{#each schemeResults as scheme}<button type="button" on:mousedown|preventDefault={()=>selectScheme(scheme)}><strong>{scheme.schemeName}</strong><small>Scheme code {scheme.schemeCode} · {scheme.latestNav==null?'Latest NAV unavailable':`Latest NAV ${moneyDecimal(scheme.latestNav)}`}</small></button>{:else}<p>No matching scheme found.</p>{/each}{/if}</div>{/if}</label>{#if selectedScheme}<div class="scheme-validated"><span>✓</span><div><strong>Verified by scheme master</strong><small>Code {selectedScheme.schemeCode} · {selectedScheme.latestNav==null?'Latest NAV unavailable':`Latest NAV ${moneyDecimal(selectedScheme.latestNav)}`}</small></div></div>{/if}</div>
      <div class="fund-section"><span class="fund-section-label">2 · SIP</span><label>Monthly SIP amount<input type="number" inputmode="decimal" min="1" bind:value={fundForm.sipAmount} /></label><div class="fund-field-pair"><label>SIP date<select bind:value={fundForm.sipDate}>{#each Array(28) as _,index}<option value={index+1}>{index+1}{index===0?'st':index===1?'nd':index===2?'rd':'th'} of every month</option>{/each}</select></label><label>Start month<input type="month" bind:value={fundForm.startMonth} /></label></div></div>
      <div class="fund-section"><span class="fund-section-label">3 · EXISTING HOLDING <em>OPTIONAL</em></span><fieldset><legend>Do you already hold this fund?</legend><label class="choice"><input type="radio" bind:group={fundForm.hasHolding} value="NO" /> No</label><label class="choice"><input type="radio" bind:group={fundForm.hasHolding} value="YES" /> Yes</label></fieldset>{#if fundForm.hasHolding==='YES'}<div class="fund-field-pair"><label>Current units<input type="number" inputmode="decimal" min="0.001" step="0.001" bind:value={fundForm.currentUnits} /></label><label>Total amount invested<input type="number" inputmode="decimal" min="0.01" bind:value={fundForm.totalInvested} /></label></div><p class="fund-disclaimer">Average purchase cost is calculated by the backend after the opening balance is recorded.</p>{/if}</div>
      {#if fundError}<p class="form-error">{fundError}</p>{/if}<div class="modal-actions"><button class="secondary" on:click={()=>showMutualFundForm=false}>Cancel</button><button class="primary" on:click={saveMutualFund} disabled={fundSaving}>{fundSaving?'Creating…':'Create SIP plan'}</button></div>
    {/if}</section></div>
{/if}
<!-- svelte-ignore a11y_click_events_have_key_events -->
{#if fundDetail}<div class="modal-backdrop fund-form-backdrop"><section class="modal fund-detail" role="dialog" aria-modal="true"><button class="close" on:click={()=>fundDetail=null}>×</button>{#if fundDetailStatus==='loading'}<p class="micro-label">FUND DETAILS</p><h2>Loading fund details…</h2>{:else if fundDetailStatus==='error'}<p class="micro-label">FUND DETAILS</p><h2>Couldn’t load this fund</h2><p>{fundDetailError}</p><button class="primary" on:click={()=>openFundDetail(fundDetail.id)}>Try again</button>{:else}<p class="micro-label">FUND DETAILS</p><h2>{fundDetail.schemeName}</h2><div class="detail-value"><span>Current value</span><strong>{money(fundDetail.currentValue)}</strong></div><div class:positive={Number(fundDetail.profitOrLoss)>=0} class:negative={Number(fundDetail.profitOrLoss)<0} class="detail-pnl"><span>Total P&amp;L</span><strong>{Number(fundDetail.profitOrLoss)>=0?'+':''}{money(fundDetail.profitOrLoss)}</strong><b>{Number(fundDetail.profitOrLossPercent)>=0?'+':''}{Number(fundDetail.profitOrLossPercent).toFixed(2)}%</b></div><div class="detail-grid"><div><span>Invested</span><b>{money(fundDetail.invested)}</b></div><div><span>Units</span><b>{Number(fundDetail.units).toFixed(3)}</b></div><div><span>Average NAV</span><b>{moneyDecimal(fundDetail.averageNav)}</b></div><div><span>Current NAV</span><b>{moneyDecimal(fundDetail.currentNav)}</b></div></div><p class="fund-disclaimer">Average NAV is based on confirmed investments. Current NAV is the latest available MFAPI value.</p>{/if}</section></div>{/if}
{#if confirmingSip}<div class="modal-backdrop fund-form-backdrop"><section class="modal fund-form" role="dialog" aria-modal="true"><button class="close" on:click={()=>confirmingSip=null}>×</button><p class="micro-label">CONFIRM SIP INVESTMENT</p><h2>Was this SIP processed?</h2><p class="module-reassurance">Units will be estimated from the NAV and marked as an estimate until you correct them from your statement.</p><div class="source-note"><strong>{confirmingSip.fund.schemeName}</strong><span>{confirmingSip.occurrence.scheduledMonth} occurrence</span></div><label>Amount invested<input type="number" min="0.01" step="0.01" bind:value={sipConfirmForm.amount}/></label><label>Transaction date<input type="date" bind:value={sipConfirmForm.transactionDate}/></label><label>NAV <span class="optional">Estimated</span><input type="number" min="0.0001" step="0.0001" bind:value={sipConfirmForm.nav} placeholder="e.g. 87.25"/></label>{#if sipConfirmError}<p class="form-error">{sipConfirmError}</p>{/if}<div class="modal-actions"><button class="secondary" on:click={()=>confirmingSip=null}>Cancel</button><button class="primary" on:click={saveSipConfirmation} disabled={sipConfirmSaving}>{sipConfirmSaving?'Confirming…':'Confirm estimate'}</button></div></section></div>{/if}
<!-- svelte-ignore a11y_click_events_have_key_events -->
{#if showNormalization}<div class="account-repair-backdrop" role="presentation" on:click={()=>showNormalization=false} on:keydown={(event)=>event.key==='Escape'&&(showNormalization=false)}><section class="account-repair-dialog" role="dialog" aria-modal="true" tabindex="-1" on:click|stopPropagation><header class="account-repair-bar"><div><span class="repair-symbol">✦</span><span><p>EXPENSE DATA ONLY</p><strong>Expense cleanup</strong></span></div><button on:click={()=>showNormalization=false}>×</button></header><div class="account-repair-content"><Normalization /></div></section></div>{/if}
<!-- svelte-ignore a11y_click_events_have_key_events -->
{#if openedStory}<div class="story-reader-backdrop" role="presentation" on:click={()=>openedStory=null} on:keydown={(event)=>event.key==='Escape'&&(openedStory=null)}><section class="story-detail" role="dialog" aria-modal="true" tabindex="-1" on:click|stopPropagation><button class="back-button" on:click={()=>openedStory=null}>← Back to stories</button><p class="micro-label">{storySource(openedStory).toUpperCase()} · {storyName(openedStory)}</p>{#if hasDeck(openedStory)}{@const cards=openedStory.cards.slice().sort((a,b)=>(a.sequence||0)-(b.sequence||0))}{@const currentCard=cards[storySlide]}<div class="story-deck">{#if cards.length>1}<div class="story-progress">{#each cards as _,index}<i class:active={index===storySlide}></i>{/each}</div>{/if}<article class={`story-slide deck-theme-${currentCard.theme||'CALM_CONTEXT'}`} on:touchstart={event=>(storyTouchStart=event.touches[0].clientX)} on:touchend={event=>endStorySwipe(event,cards.length)}>{#if currentCard.eyebrow}<p class="slide-eyebrow">{currentCard.eyebrow}</p>{/if}{#if currentCard.layout==='HERO_STAT'&&currentCard.components?.[0]}<div class="story-amount"><span>{currentCard.components[0].label}</span><strong>{currentCard.components[0].displayValue}</strong></div>{/if}<h1>{currentCard.title}</h1><p>{currentCard.body}</p>{#if currentCard.components?.length}<div class="observation-components">{#each currentCard.components as component}<div><span>{component.label}</span><strong>{component.displayValue}</strong></div>{/each}</div>{/if}{#each currentCard.actions||[] as action}{#if action.type==='OPEN_EVIDENCE'}<button class="story-action" on:click={()=>showStoryEvidence=true}>{action.label}</button>{/if}{/each}</article>{#if cards.length>1}<div class="story-deck-controls"><button disabled={storySlide===0} on:click={()=>storySlide-=1}>←</button><span>{storySlide+1} of {cards.length}</span><button disabled={storySlide===cards.length-1} on:click={()=>storySlide+=1}>Next →</button></div>{/if}</div>{/if}</section></div>{/if}
<!-- svelte-ignore a11y_click_events_have_key_events -->
{#if showStoryEvidence}<div class="modal-backdrop" on:click={()=>showStoryEvidence=false} on:keydown={(event)=>event.key==='Escape'&&(showStoryEvidence=false)} role="presentation"><section class="modal" on:click|stopPropagation role="dialog" aria-modal="true" tabindex="-1"><button class="close" on:click={()=>showStoryEvidence=false}>×</button><p class="micro-label">SUPPORTING EVIDENCE</p><h2>{openedStory?.evidence?.title||'Transactions behind this story'}</h2>{#if evidenceItems.length}<p class="evidence-total">{evidenceItems.length} {evidenceItems.length===1?'transaction':'transactions'}</p><div class="evidence-list">{#each evidenceItems as item}<div class="evidence-row"><div><strong>{item.merchant}</strong><span>{item.date}{item.date&&item.category?' · ':''}{item.category}</span></div><b>− {item.amount}</b></div>{/each}</div>{:else}<div class="empty-state evidence-empty"><span>◌</span><h2>No transactions attached</h2><p>This story does not include individual transactions to display.</p></div>{/if}</section></div>{/if}
{#if editing}<div class="modal-backdrop"><section class="modal" role="dialog" aria-modal="true" tabindex="-1"><button class="close" on:click={()=>editing=null}>×</button><p class="micro-label">AI-CAPTURED EXPENSE</p><h2>Edit transaction</h2><div class="source-note"><strong>Captured from your message</strong><span>Review the details below before saving.</span></div><label>Amount<input type="number" inputmode="decimal" min="0.01" step="0.01" bind:value={editAmount}/></label><label>Transaction date<input type="date" max={new Date().toISOString().slice(0,10)} bind:value={editDate}/></label>{#if optionsStatus==='loading'}<p class="edit-options-status">Loading categories, merchants, and accounts…</p>{:else if optionsStatus==='error'}<p class="form-error">{optionsError}</p>{:else}<label>Category<select value={editCategory} on:change={changeEditCategory}><option value="" disabled>Select a category</option>{#each editOptions.categories as option}<option value={option.name}>{option.name}</option>{/each}</select></label><label>Subcategory<select bind:value={editSubcategory} disabled={!editCategory}><option value="" disabled>Select a subcategory</option>{#each editSubcategories as option}<option value={option}>{option}</option>{/each}</select></label><label>Merchant<select bind:value={editMerchantId}><option value="" disabled>Select a merchant</option>{#each editOptions.merchants as option}<option value={String(option.id)}>{option.name}</option>{/each}</select></label><label>Source account<select bind:value={editAccountId}><option value="" disabled>Select an account</option>{#each editOptions.accounts as option}<option value={String(option.id)}>{option.name}</option>{/each}</select></label>{/if}{#if actionError}<p class="form-error">{actionError}</p>{/if}<div class="modal-actions"><button class="secondary" on:click={()=>editing=null}>Cancel</button><button class="primary" on:click={saveEdit} disabled={saving||optionsStatus!=='ready'}>{saving?'Saving…':'Save changes'}</button></div></section></div>{/if}
{#if deleting}<div class="modal-backdrop"><section class="modal" role="alertdialog" aria-modal="true" tabindex="-1"><p class="micro-label">DELETE TRANSACTION</p><h2>Delete {merchant(deleting)}?</h2><p>This updates the calendar and monthly totals.</p><div class="modal-actions"><button class="secondary" on:click={()=>deleting=null}>Cancel</button><button class="primary delete-confirm" on:click={confirmDelete}>Delete</button></div></section></div>{/if}
{#if handoff}<div class="modal-backdrop"><section class="modal whatsapp-handoff" role="dialog" aria-modal="true" tabindex="-1"><button class="close" on:click={()=>handoff=null}>×</button><p class="micro-label">WHATSAPP READY</p><h2>Continue in WhatsApp</h2><p>Send the missing transaction for {dateLabel(`${handoff.date}T12:00:00`)}.</p>{#if handoff.whatsappUrl}<a class="center-action whatsapp-action" href={handoff.whatsappUrl} target="_blank" rel="noopener">Open WhatsApp</a>{/if}<button class="auth-secondary" on:click={()=>handoff=null}>Done</button></section></div>{/if}
